package com.honorablemobile

import android.app.AlertDialog
import android.net.Uri
import app.honorable.editor.EditorAccessMode
import org.junit.Assert.*
import org.junit.Test

/** Actual rough-cut approval/model gates; no inference or Android widget execution. */
class VideoRoughCutReviewTest {
 private val unsafe=Class.forName("sun.misc.Unsafe").getDeclaredField("theUnsafe").apply{isAccessible=true}.get(null)as sun.misc.Unsafe
 private fun set(a:Any,n:String,v:Any?)=a.javaClass.getDeclaredField(n).apply{isAccessible=true}.set(a,v)
 private fun get(a:Any,n:String)=a.javaClass.getDeclaredField(n).apply{isAccessible=true}.get(a)
 private fun call(a:Any,n:String,vararg args:Any?)=a.javaClass.declaredMethods.single{it.name==n&&it.parameterCount==args.size}.apply{isAccessible=true}.invoke(a,*args)
 private fun activity()=(unsafe.allocateInstance(HonorableVideoEditorActivity::class.java)as HonorableVideoEditorActivity).also{val p=VideoEditProject(5000);p.restore(listOf(VideoSegment(0,5000,captions=listOf(VideoCaption(0,500,"A"),VideoCaption(1000,1500,"B")),captionSourceUri="content://synthetic/subtitles")),soundtrack=VideoSoundtrack("content://synthetic/music",10000,loop=false));set(it,"project",p);set(it,"source",Uri.parse("content://synthetic/video"));set(it,"primaryDurationMs",5000L);set(it,"accessMode",EditorAccessMode.GUEST_BASIC);set(it,"workspaceActive",true);set(it,"importedSources",linkedMapOf<String,VideoSource>())}
 private fun showing(d:AlertDialog,value:Boolean){android.app.Dialog::class.java.getDeclaredField("mDecor").apply{isAccessible=true}.set(d,if(value)unsafe.allocateInstance(android.view.View::class.java)else null)}
 private fun dialog()=(unsafe.allocateInstance(AlertDialog::class.java)as AlertDialog).also{showing(it,true)}
 private fun capture(a:HonorableVideoEditorActivity)=call(a,"captureCaptionReview")as VideoCaptionReviewState
 private fun inspectorActivity():HonorableVideoEditorActivity=activity().also{a->val p=get(a,"project")as VideoEditProject;p.restore(p.segments.map{it.copy(title="Styled",grade=VideoGrade(.123f,1.234f,.876f,.111f,-.222f),titleStyle=VideoTitleStyle(2,.061f,true,false))},soundtrack=p.soundtrack)}
 private fun editor(a:HonorableVideoEditorActivity):AlertDialog=dialog().also{set(a,"inspectorReviewDialog",it);set(a,"captionReviewDialogs",linkedSetOf(it))}
 private fun commit(a:HonorableVideoEditorActivity,d:AlertDialog,r:VideoCaptionReviewState,action:()->Unit):Boolean {val p=get(a,"project")as VideoEditProject;return call(a,"commitInspectorReview",d,r,p,0,p.segments[0],action)as Boolean}
 private fun selection(a:HonorableVideoEditorActivity):VideoSceneSelection {val p=get(a,"project")as VideoEditProject;return VideoSceneSelection.capture(p.segments,0,0,5000)}
 private fun proposed(s:VideoSceneSelection)=VideoRoughCut.assemble(s.clips,listOf(2500L),2000L)
 private fun apply(a:HonorableVideoEditorActivity,d:AlertDialog,r:VideoCaptionReviewState,p:VideoEditProject,s:VideoSceneSelection,clips:List<VideoSegment> = proposed(s))=call(a,"commitRoughCutReview",d,r,p,s,p.soundtrack,clips)as Boolean
 @Test fun acceptedDraftPreservesSettingsAndSoundtrackWithOneUndoAndCodec(){val a=activity();val p=get(a,"project")as VideoEditProject;val before=p.segments;val music=p.soundtrack;val s=selection(a);val r=capture(a);val d=editor(a);val clips=proposed(s);assertTrue(apply(a,d,r,p,s));assertEquals(clips,p.segments);assertSame(music,p.soundtrack);assertEquals(before[0].copy(startMs=clips[0].startMs,endMs=clips[0].endMs),clips[0]);assertNull(get(a,"inspectorReviewDialog"));val draft=VideoDraft(5000,p.segments,0,0,clips[0].startMs,clips[0].endMs,soundtrack=music);assertEquals(draft,VideoDraftCodec.decode(VideoDraftCodec.encode(draft),5000));assertTrue(p.undo());assertEquals(before,p.segments);assertSame(music,p.soundtrack);assertFalse(p.canUndo)}
 @Test fun consumedVisibleApprovalCannotReplayAfterUndo(){val a=activity();val p=get(a,"project")as VideoEditProject;val before=p.segments;val s=selection(a);val r=capture(a);val d=editor(a);assertTrue(apply(a,d,r,p,s));assertTrue(p.undo());assertFalse(apply(a,d,r,p,s));assertEquals(before,p.segments);assertFalse(p.canUndo);assertTrue(p.canRedo)}
 @Test fun replacedOwnerCannotConsumeSuccessor(){val a=activity();val p=get(a,"project")as VideoEditProject;val s=selection(a);val r=capture(a);val old=editor(a);val latest=editor(a);assertFalse(apply(a,old,r,p,s));assertSame(latest,get(a,"inspectorReviewDialog"));assertFalse(p.canUndo);assertTrue(apply(a,latest,r,p,s))}
 @Test fun staleForegroundRecoverySourceAndGenerationRefuseWithoutModelChange(){for(flag in listOf("pause","saving","analysis","draft","import","range","bytes","blocked","checking","source","duration","mode","generation","clip")){val a=activity();val p=get(a,"project")as VideoEditProject;val before=p.segments;val s=selection(a);val r=capture(a);val d=editor(a);when(flag){"pause"->set(a,"workspaceActive",false);"saving"->set(a,"saving",true);"analysis"->set(a,"analyzing",true);"draft"->set(a,"draftBusy",true);"import"->set(a,"importing",true);"range"->set(a,"pendingRange",0L to 1000L);"bytes"->set(a,"recoveryBytes",byteArrayOf(1));"blocked"->set(a,"recoveryBlocked",true);"checking"->set(a,"recoveryChecking",true);"source"->set(a,"source",Uri.parse("content://synthetic/other"));"duration"->set(a,"primaryDurationMs",6000L);"mode"->set(a,"accessMode",EditorAccessMode.ACCOUNT);"generation"->set(a,"captionReviewGeneration",1L);else->set(a,"selectedClip",1)};assertEquals(flag,false,call(a,"canReviewRoughCut",r,p,s,p.soundtrack));assertFalse(flag,apply(a,d,r,p,s));assertSame(before,p.segments);assertFalse(p.canUndo);assertNull(get(a,"inspectorReviewDialog"))}}
 @Test fun hiddenUntrackedChangedMusicOrForeignProjectCannotApply(){for(flag in listOf("hidden","untracked","music","project")){val a=activity();val p=get(a,"project")as VideoEditProject;val s=selection(a);val r=capture(a);val d=editor(a);when(flag){"hidden"->showing(d,false);"untracked"->set(a,"captionReviewDialogs",linkedSetOf<AlertDialog>());"music"->p.setSoundtrack(p.soundtrack!!.copy(volume=.5f))};val before=p.segments;assertFalse(apply(a,d,r,if(flag=="project")VideoEditProject(5000)else p,s));assertSame(before,p.segments);assertEquals(flag=="music",p.canUndo)}}
 @Test fun unchangedDraftConsumesApprovalWithoutInventingUndo(){val a=activity();val p=get(a,"project")as VideoEditProject;val s=selection(a);val r=capture(a);val d=editor(a);assertTrue(apply(a,d,r,p,s,s.clips));assertFalse(p.canUndo);assertNull(get(a,"inspectorReviewDialog"));assertFalse(apply(a,d,r,p,s,s.clips))}
 @Test fun progressRequiresCurrentForegroundGenerationProjectAndMode(){for(flag in listOf("current","pause","generation","mode","project")){val a=activity();val p=get(a,"project")as VideoEditProject;val r=capture(a);set(a,"analyzing",true);when(flag){"pause"->set(a,"workspaceActive",false);"generation"->set(a,"captionReviewGeneration",1L);"mode"->set(a,"accessMode",EditorAccessMode.ACCOUNT)};assertEquals(flag,flag=="current",call(a,"canReportRoughCut",r,if(flag=="project")VideoEditProject(5000)else p));assertFalse(p.canUndo)}}
}
